/**
 * The Ancient Seas Trilogy title page, which is the site root: everything about it that is data.
 *
 * Pure — no DOM, no React, no era content — so `npm run ancientseas` can check it headless: that
 * the version parameter defaults sensibly, that every game links to an entry page that exists and
 * shows a title image that exists, that every image version 2 asks for has a brief open in
 * docs/image-requests.md, and that the page never asks the network for a requested file that has
 * not been delivered (`delivered.json`, regenerated by `npm run ancientseas:delivered`).
 *
 * Two versions, picked by `?version=`:
 *   2 — the default, and what the page is: one composition in the title paintings' own style,
 *       assembled from individually requested pieces — an engraved trilogy title, engraved game
 *       titles, and the animals and plants arranged round them. Until a piece is delivered its
 *       slot draws a stand-in.
 *   1 — the earlier draft, kept for comparison: the three games' own title paintings, whole, on a
 *       dark ground shaped to their vignettes.
 *
 * Neither version draws a switch between them: the parameter is a way to look at the other draft,
 * not something the page offers a visitor.
 */
import DELIVERED from './delivered.json';

export type PageVersion = 1 | 2;
export const DEFAULT_VERSION: PageVersion = 2;
export const VERSIONS: readonly PageVersion[] = [1, 2];

/** `?version=2` → 2; anything else, including nothing, is the default. */
export function parseVersion(search: string): PageVersion {
  const raw = new URLSearchParams(search).get('version');
  return raw !== null && VERSIONS.includes(Number(raw) as PageVersion) ? (Number(raw) as PageVersion) : DEFAULT_VERSION;
}

export type EraId = 'cambrian' | 'devonian' | 'triassic';

export interface GameLink {
  readonly id: EraId;
  readonly title: string;
  /** The game's own folder, relative to the app root — which is this page. */
  readonly path: string;
  /** The game's own composed title painting, the one its title screen shows. */
  readonly art: string;
  readonly artWidth: number;
  readonly artHeight: number;
  /** The wordmark the interface uses, which is the game's own (`npm run logos`). */
  readonly wordmark: string;
  /** Period, as the game's own copy puts it (`copy.taglineEm`); the test keeps these in step. */
  readonly when: string;
  readonly tagline: string;
}

