/**
 * The one animal of each era that arches over its title — the one the page lifts when the pointer
 * is on that game, so the link is the title and the creature above it together.
 */
export const BIG_ANIMAL: Readonly<Record<EraId, string>> = {
  cambrian: 'anomalocaris', devonian: 'dunkleosteus', triassic: 'cymbospondylus',
};

/**
 * Which era each animal belongs to, so the page can light an era's own animal with its title and
 * the test can check that an era's animals really do gather under it rather than being strung
 * across the plate.
 */
export const ANIMAL_ERA: Readonly<Record<string, EraId>> = {
  anomalocaris: 'cambrian', trilobite: 'cambrian', hallucigenia: 'cambrian',
  dunkleosteus: 'devonian', tiktaalik: 'devonian', bothriolepis: 'devonian',
  cymbospondylus: 'triassic', nautiloid: 'triassic', placodont: 'triassic',
};

/** Every file the page asks for: the version-1 wordmark and each version-2 drawing once, however many slots share it. */
export const REQUESTED: readonly string[] = [...new Set([TRILOGY_LOGO, ...SLOTS.map((s) => s.file)])];

const delivered = new Set<string>(DELIVERED.files);
/** True once the file has been dropped into public/ and `npm run ancientseas:delivered` has seen it. */
export const isDelivered = (file: string) => delivered.has(file);

/** What a slot actually draws: the delivered request, a shipped stand-in, or a placeholder. */
export type SlotSource = { kind: 'delivered'; src: string } | { kind: 'stand-in'; src: string } | { kind: 'placeholder' };
export function sourceFor(slot: Slot): SlotSource {
  if (isDelivered(slot.file)) return { kind: 'delivered', src: slot.file };
  if (slot.standIn) return { kind: 'stand-in', src: slot.standIn };
  return { kind: 'placeholder' };
}
